// ==========================================
// DLC認証
// ==========================================
async function gate() {

   const userInput = prompt(
      "ダウンロードコードを入力してください:",
      ""
   );

   if (userInput === null) {
      return;
   }

   const code = userInput.trim();

   if (code === "") {
      alert("ダウンロードコードを入力してください。");
      return;
   }

   if (!/^[a-zA-Z0-9-]+$/.test(code)) {
      alert("半角英数字とハイフンのみを入力してください。");
      return;
   }


   // 商品検索
   const product =
      await findProduct(code);


   if (!product) {
      alert("ダウンロードコードが正しくありません。");
      return;
   }


   // 正規アクセス用一時情報
   sessionStorage.setItem(
      "cadenceDlcAccess",
      JSON.stringify({
         token: product.token,
         zipPassword: product.zipPassword,
         expiresAt:
            Date.now() +
            (30 * 60 * 1000)
      })
   );


   // DLCページへ
   location.href =
      "dlc.html?t=" +
      encodeURIComponent(
         product.token
      );
}


// ==========================================
// 商品検索
// ==========================================
async function findProduct(code) {

   console.log("入力コード:", code);

   for (const encrypted of ENCRYPTED_PRODUCTS) {

      try {

         console.log(
            "復号試行:",
            encrypted.id
         );

         const product =
            await decryptProduct(
               encrypted
            );

         console.log(
            "復号結果:",
            encrypted.id,
            product
         );

         if (!product) {
            console.warn(
               "product が null:",
               encrypted.id
            );
            continue;
         }


         const hash =
            await createAuthHash(
               code,
               product.key
            );


         console.log(
            "hash比較:",
            {
               id: encrypted.id,
               calculated: hash,
               expected: product.hash,
               match:
                  hash === product.hash
            }
         );


         if (
            hash ===
            product.hash
         ) {

            console.log(
               "認証成功:",
               product
            );

            return product;
         }

      } catch (error) {

         console.error(
            "商品処理エラー:",
            encrypted.id,
            error
         );

         continue;
      }
   }


   console.error(
      "一致商品なし"
   );

   return null;
}


// ==========================================
// 認証用ハッシュ生成
// ==========================================
async function createAuthHash(
   code,
   productKey
) {

   // 1段目
   const firstHash =
      await sha256(code);


   // 商品別キーを混ぜる
   const source =
      productKey +
      ":" +
      firstHash +
      ":Cadence-DLC";


   // 2段目
   return await sha256(
      source
   );
}


// ==========================================
// SHA-256
// ==========================================
async function sha256(text) {

   const data =
      new TextEncoder()
         .encode(text);


   const hash =
      await crypto.subtle.digest(
         "SHA-256",
         data
      );


   return Array.from(
      new Uint8Array(hash)
   )
      .map(
         byte =>
            byte
               .toString(16)
               .padStart(2, "0")
      )
      .join("");
}